-- Optimistic timestamp guard: a concurrent editorial change rolls back the entire batch.
DO $apply_seo$
DECLARE updated_count integer;
BEGIN
  UPDATE public.services AS s
  SET short_text = p.short_text,
      long_text = p.long_text,
      meta_title = p.meta_title,
      meta_description = p.meta_description,
      geo_focus = p.geo_focus,
      custom_benefits = p.custom_benefits,
      custom_faqs = p.custom_faqs
  FROM jsonb_to_recordset($seo_data$[{"slug":"natursteinarbeiten","short_text":"Naturstein für Terrassen, Gartenwege, Mauern und Stufen. Wir stimmen Material, Oberfläche und Aufbau auf Ihr Vorhaben in Hattersheim und im Rhein-Main-Gebiet ab.","long_text":"Eine Natursteinterrasse, eine Natursteinmauer oder Stufen zwischen zwei Gartenebenen: Naturstein lässt sich dort einsetzen, wo Gestaltung und Nutzung zusammenpassen sollen. Loni GalaBau aus Hattersheim übernimmt Natursteinarbeiten im Rhein-Main-Gebiet. Gemeinsam besprechen wir, welche Flächen Sie verändern möchten und wie sich der Stein in Ihren Garten einfügen soll. Auch Anschlüsse an vorhandene Wege, Beete und das Haus beziehen wir ein.\n\nGranit, Sandstein, Basalt oder Kalkstein unterscheiden sich in Farbe, Struktur und Oberflächenwirkung. Entscheidend ist aber auch der konkrete Einsatz: Ein häufig genutzter Gartenweg stellt andere Anforderungen als eine Beetbegrenzung. Wir stimmen Material, Format und Bearbeitung auf Ihr Vorhaben ab. Ein Muster hilft dabei, Farben und Oberflächen im Zusammenhang mit Fassade, Pflanzen und vorhandenen Belägen zu betrachten.\n\nVor der Ausführung prüfen wir die Ausgangssituation und klären den vereinbarten Aufbau. Bei einer Terrasse gehören Höhen, Untergrund, Gefälle und Wasserführung zur Planung. Bei Mauern und Treppen kommen Verlauf, Übergänge und die örtlichen Bedingungen hinzu. Ob eine Konstruktion zusätzliche Planung benötigt, besprechen wir vor Beginn. So werden die sichtbare Gestaltung und die Arbeiten unter der Oberfläche gemeinsam betrachtet.\n\nDie Kosten von Natursteinarbeiten hängen unter anderem vom Stein, der Fläche, Zuschnitten, der Vorbereitung und der Erreichbarkeit ab. Beschreiben Sie uns, ob eine neue Fläche entstehen oder ein vorhandener Bereich umgestaltet werden soll. Fotos, ungefähre Maße und Angaben zur Zufahrt erleichtern das erste Gespräch. Anschließend stimmen wir Material und Leistungsumfang ab und erstellen ein Angebot für die besprochenen Arbeiten.","meta_title":"Natursteinarbeiten in Hattersheim | Loni GalaBau","meta_description":"Natursteinarbeiten in Hattersheim und Rhein-Main: Terrassen, Wege, Mauern und Stufen. Material und Aufbau persönlich abstimmen. Projekt anfragen.","geo_focus":"Hattersheim & Rhein-Main","custom_benefits":[{"t":"Terrassen und Gartenwege","d":"Natursteinflächen passend zu Nutzung, Format und vorhandenen Anschlüssen planen und ausführen."},{"t":"Mauern und Stufen","d":"Gartenbereiche einfassen und Höhenunterschiede mit einer zum Grundstück passenden Lösung gestalten."},{"t":"Material und Oberfläche","d":"Steinart, Bearbeitung und Fugenbild im Zusammenhang mit Haus und Garten auswählen."}],"custom_faqs":[{"q":"Kann Naturstein mit einer vorhandenen Terrasse kombiniert werden?","a":"Das lässt sich anhand von Höhen, Aufbau und Zustand des Bestands beurteilen. Fotos geben einen ersten Eindruck; die Anschlüsse und eine passende Materialauswahl besprechen wir für Ihr Grundstück."},{"q":"Was ist bei der Pflege einer Natursteinterrasse zu beachten?","a":"Reinigung und Pflege richten sich nach Steinart, Oberfläche und Fugen. Wir besprechen die Hinweise für das ausgewählte Material. Nicht jedes Reinigungsmittel eignet sich für jeden Naturstein."},{"q":"Übernehmen Sie auch einzelne Natursteinstufen oder eine Gartenmauer?","a":"Sie können auch einen einzelnen Gartenbereich anfragen. Senden Sie uns Fotos, ungefähre Maße und eine Beschreibung. Wir klären, welche Arbeiten und gegebenenfalls zusätzliche Planung dafür erforderlich sind."}],"expected_updated_at":"2026-09-28 14:38:07.317112+00"},{"slug":"gartengestaltung","short_text":"Einen Garten neu anlegen oder vorhandene Bereiche umgestalten: Wir verbinden Wege, Terrasse, Rasen und Pflanzen zu einem Garten, der zu Ihrem Alltag passt.","long_text":"Sie möchten einen vorhandenen Garten umgestalten oder nach einem Neubau einen Garten anlegen lassen? Loni GalaBau begleitet Ihre Gartengestaltung in Hattersheim und im Rhein-Main-Gebiet. Am Anfang steht die Nutzung: Wo möchten Sie sitzen, wie bewegen Sie sich durch den Garten und welche Bereiche sollen frei bleiben? Aus Ihren Wünschen und den Bedingungen des Grundstücks entsteht eine passende Aufteilung.\n\nZur Gartenplanung gehören mehr als Pflanzen und Beläge. Wir betrachten vorhandene Höhen, sonnige und schattige Bereiche, Zugänge und Anschlüsse an das Haus. Terrasse, Gartenwege, Rasen und Beete sollen sinnvoll zusammenarbeiten. Bestehende Pflanzen oder gut erhaltene Flächen können dabei Teil der Gestaltung bleiben. Für eine weitergehende Planung beziehen wir bei Bedarf unseren Planungspartner ein und stimmen den Umfang mit Ihnen ab.\n\nEin moderner, pflegeleichter Garten beginnt mit Entscheidungen, die zum Alltag passen. Wie viel Zeit möchten Sie für Rasen und Beete aufbringen? Welche Wege werden häufig genutzt? Wir besprechen Pflanzenauswahl, Flächenaufteilung und Materialien mit Blick auf Standort und Pflegeaufwand. Pflegeleicht bedeutet dabei nicht pflegefrei. Auch Bewässerung, Sichtschutz und die Ableitung von Regenwasser lassen sich von Anfang an berücksichtigen.\n\nDie Umsetzung kann den gesamten Außenbereich oder einzelne Gartenbereiche umfassen. Wenn Sie in Bauabschnitten arbeiten möchten, besprechen wir die Reihenfolge und notwendige Vorarbeiten. Für ein Angebot sind Fläche, Bestand, Materialwünsche, Zufahrt und gewünschter Leistungsumfang wichtig. Bringen Sie gern Fotos, eine Skizze oder Beispiele mit. Gemeinsam klären wir, welche Ideen zu Ihrem Grundstück passen und wie daraus ein konkretes Gartenprojekt wird.","meta_title":"Gartengestaltung in Hattersheim | Loni GalaBau","meta_description":"Gartengestaltung in Hattersheim und Rhein-Main: Garten neu anlegen oder umgestalten, Terrasse, Wege und Pflanzen abstimmen. Jetzt Ihr Vorhaben besprechen.","geo_focus":"Hattersheim & Rhein-Main","custom_benefits":[{"t":"Garten neu anlegen","d":"Wege, Sitzplätze, Rasen und Beete auf Grundstück und Nutzung abstimmen."},{"t":"Bestehenden Garten umgestalten","d":"Vorhandene Pflanzen und Flächen einbeziehen und einzelne Bereiche gezielt erneuern."},{"t":"Pflege im Alltag mitdenken","d":"Pflanzen, Bewässerung und Flächen so auswählen, dass sie zu Ihrem gewünschten Pflegeaufwand passen."}],"custom_faqs":[{"q":"Lässt sich auch ein kleiner Garten neu gestalten?","a":"Ja. Gerade bei wenig Platz lohnt es sich, Sitzplatz, Wege und Pflanzflächen gemeinsam zu betrachten. Wir besprechen, welche Nutzungen Ihnen wichtig sind und was auf Ihrem Grundstück sinnvoll untergebracht werden kann."},{"q":"Können vorhandene Pflanzen bei der Umgestaltung bleiben?","a":"Wir beziehen den Bestand in die Planung ein. Ob Pflanzen bleiben oder umgesetzt werden können, hängt unter anderem von ihrem Zustand, Standort und den vorgesehenen Bauarbeiten ab."},{"q":"Was beeinflusst die Kosten einer Gartengestaltung?","a":"Neben der Fläche sind vor allem Rückbau, Erdarbeiten, Materialien, Pflanzenauswahl und Zugänglichkeit entscheidend. Deshalb stimmen wir den Umfang konkret ab, statt einen pauschalen Quadratmeterpreis für sehr unterschiedliche Gärten zu nennen."}],"expected_updated_at":"2026-09-28 14:38:07.466322+00"},{"slug":"pflasterarbeiten","short_text":"Einfahrten, Terrassen und Gartenwege pflastern lassen: Wir planen Belag, Unterbau und Entwässerung zusammen und setzen die abgestimmten Arbeiten um.","long_text":"Eine Einfahrt muss andere Belastungen aufnehmen als ein Gartenweg oder ein Sitzplatz. Für Pflasterarbeiten in Hattersheim und im Rhein-Main-Gebiet stimmen wir deshalb den sichtbaren Belag und den Aufbau darunter gemeinsam ab. Loni GalaBau pflastert Einfahrten, Terrassen und Wege nach den Anforderungen Ihres Grundstücks. Dabei berücksichtigen wir auch Anschlüsse an Garage, Haustür und vorhandene Gartenflächen.\n\nZu Beginn klären wir, wie die Fläche genutzt werden soll. Welche Fahrzeuge befahren die Einfahrt? Soll ein Weg bequem vom Haus zum Garten führen? Welche Höhen sind bereits vorgegeben? Daraus ergeben sich wichtige Entscheidungen für Material, Unterbau und Einfassungen. Betonstein, Naturstein oder Klinker bieten unterschiedliche Formate und Gestaltungsmöglichkeiten. Oberfläche, Farbe und Verlegemuster wählen wir passend zur Umgebung und zur vereinbarten Nutzung.\n\nJe nach Ausgangssituation gehören Rückbau, Aushub, Herstellung der Tragschicht, Randeinfassungen, Verlegung und Verfugung zum Leistungsumfang. Das Regenwasser berücksichtigen wir bei Höhen und Gefälle von Anfang an. Falls Entwässerungsrinnen oder weitere Maßnahmen erforderlich sind, stimmen wir diese mit der Pflasterfläche ab. Auch vorhandenes Pflaster können wir auf eine mögliche Wiederverwendung prüfen.\n\nWas Pflasterarbeiten kosten, hängt nicht allein von den Quadratmetern ab. Der bestehende Untergrund, Entsorgung, Material, Zuschnitte, Einfassungen und Zufahrt beeinflussen den Aufwand. Für ein erstes Gespräch helfen Fotos, ungefähre Maße und Angaben zur späteren Belastung. Nach Klärung des Bestands erhalten Sie ein Angebot über die besprochenen Arbeiten. So können Sie nachvollziehen, welche Leistungen für Ihre neue Einfahrt, Terrasse oder Ihren Gartenweg vorgesehen sind.","meta_title":"Pflasterarbeiten in Hattersheim | Loni GalaBau","meta_description":"Einfahrt, Terrasse oder Gartenweg pflastern lassen in Hattersheim und Rhein-Main. Pflasterarbeiten mit abgestimmtem Unterbau und Entwässerung anfragen.","geo_focus":"Hattersheim & Rhein-Main","custom_benefits":[{"t":"Einfahrten pflastern","d":"Belag und Unterbau auf Fahrzeuge, Zufahrt und die vorhandenen Höhen abstimmen."},{"t":"Terrassen und Wege","d":"Sitzplätze und Verbindungen im Garten mit passenden Materialien und Einfassungen gestalten."},{"t":"Unterbau und Entwässerung","d":"Tragschichten, Gefälle und Wasserführung als Teil der gesamten Fläche planen."}],"custom_faqs":[{"q":"Kann eine bestehende Einfahrt neu gepflastert werden?","a":"Ja, eine Erneuerung lässt sich anfragen. Wir prüfen den vorhandenen Aufbau und besprechen, was bleiben kann und welche Schichten erneuert werden müssen. Ein neuer Belag allein behebt nicht jede Ursache für abgesackte Flächen."},{"q":"Können alte Pflastersteine wiederverwendet werden?","a":"Das hängt von Zustand, Menge und gewünschter Nutzung ab. Wir sehen uns das Material an und besprechen Sortierung, mögliche Ergänzungen und Neuverlegung. Eine Wiederverwendung wird im Leistungsumfang ausdrücklich festgehalten."},{"q":"Wie lässt sich ein Angebot für Pflasterarbeiten vergleichen?","a":"Achten Sie darauf, ob Rückbau, Aushub, Entsorgung, Unterbau, Steine, Einfassungen und Entwässerung enthalten sind. Angebote mit gleichem Flächenmaß können unterschiedliche Arbeiten umfassen."}],"expected_updated_at":"2026-09-28 14:38:07.598531+00"},{"slug":"bewaesserungsanlagen","short_text":"Bewässerungsanlagen für Rasen und Beete: Wir planen Regner, Tropfbewässerung und Steuerung passend zu Ihren Gartenflächen und dem vorhandenen Wasseranschluss.","long_text":"Eine Bewässerungsanlage im Garten soll die richtigen Flächen versorgen und sich verständlich bedienen lassen. Loni GalaBau plant und installiert Gartenbewässerung in Hattersheim und im Rhein-Main-Gebiet. Wir betrachten Rasen, Beete und Pflanzbereiche einzeln und stimmen die Anlage auf deren Nutzung sowie den vorhandenen Wasseranschluss ab. Das ist bei einer Gartenneuanlage ebenso wichtig wie bei der Nachrüstung im Bestand.\n\nRasenflächen lassen sich mit passend angeordneten Regnern bewässern; für viele Pflanzbereiche kommen Tropfleitungen infrage. Welche Kombination sinnvoll ist, hängt von Form und Größe der Flächen, der Bepflanzung und den örtlichen Bedingungen ab. Wir besprechen, welche Bereiche gemeinsam versorgt werden können und wo eine getrennte Steuerung sinnvoll ist. Wege, Sitzplätze und andere Flächen beziehen wir bei der Anordnung mit ein.\n\nVor der Installation klären wir Leitungswege, Anschlussmöglichkeiten und die gewünschte Bedienung. Eine zeitgesteuerte Bewässerung, eine Steuerung per App oder ergänzende Sensoren kommen je nach Vorhaben infrage. Umfang und Ausstattung werden vor der Ausführung vereinbart. Eine automatische Anlage ersetzt dabei nicht die passende Einstellung: Wetter, Jahreszeit und Pflanzenbedarf müssen bei der Nutzung berücksichtigt werden.\n\nBei bestehenden Gärten besprechen wir auch, wo Leitungen verlegt werden können und welche Flächen anschließend wiederherzustellen sind. Der Aufwand ergibt sich unter anderem aus Flächengröße, Zahl der Bewässerungsbereiche, Anschlussbedingungen und Steuerung. Für Ihre Anfrage helfen ein Grundstücksplan oder eine Skizze, Fotos und Angaben zum Wasseranschluss. Nach der Installation erklären wir die vereinbarte Bedienung und besprechen Pflege, Kontrolle und die Vorbereitung auf die kalte Jahreszeit.","meta_title":"Bewässerungsanlagen in Hattersheim | Loni GalaBau","meta_description":"Bewässerungsanlage für Ihren Garten in Hattersheim und Rhein-Main planen lassen: Rasen, Beete, Regner und Tropfbewässerung passend zum Grundstück.","geo_focus":"Hattersheim & Rhein-Main","custom_benefits":[{"t":"Rasen und Beete versorgen","d":"Regner und Tropfleitungen entsprechend den unterschiedlichen Gartenflächen auswählen."},{"t":"Leitungen und Anschlüsse","d":"Wasseranschluss, Leitungswege und notwendige Arbeiten im vorhandenen Garten abstimmen."},{"t":"Steuerung und Bedienung","d":"Zeitprogramme, mögliche Sensoren und gewünschte Bedienfunktionen für Ihr Vorhaben klären."}],"custom_faqs":[{"q":"Kann eine Bewässerungsanlage im bestehenden Garten nachgerüstet werden?","a":"Eine Nachrüstung ist grundsätzlich planbar. Entscheidend sind Wasseranschluss, Leitungswege und die vorhandenen Flächen. Wir besprechen, welche Eingriffe und Wiederherstellungsarbeiten bei Ihrem Garten erforderlich wären."},{"q":"Sind Tropfbewässerung oder Versenkregner besser?","a":"Das richtet sich nach der zu bewässernden Fläche. Für Beete und Pflanzreihen kommen andere Lösungen infrage als für zusammenhängende Rasenflächen. In einem Garten kann eine abgestimmte Kombination sinnvoll sein."},{"q":"Spart automatische Gartenbewässerung immer Wasser?","a":"Eine pauschale Einsparung lässt sich nicht versprechen. Verbrauch und Ergebnis hängen von Auslegung, Einstellung, Wetter und Pflanzenbedarf ab. Eine gut abgestimmte Steuerung hilft, Bewässerung gezielt zu planen und anzupassen."}],"expected_updated_at":"2026-09-28 14:38:07.716527+00"},{"slug":"zaunarbeiten","short_text":"Zaunbau, Gartentore und Sichtschutz für Ihr Grundstück. Wir stimmen Material, Höhe, Verlauf und Montage auf Ihre Wünsche und die Gegebenheiten vor Ort ab.","long_text":"Ein Gartenzaun markiert Grenzen, ein Tor ordnet den Zugang und ein Sichtschutz schafft einen geschützteren Sitzplatz. Loni GalaBau übernimmt Zaunarbeiten und Zaunbau in Hattersheim und im Rhein-Main-Gebiet. Gemeinsam klären wir, welche Aufgabe Ihre Anlage erfüllen soll: eine offene Einfriedung, mehr Privatsphäre oder eine Kombination mit einem passenden Gartentor.\n\nHolz, Metall, Doppelstabmatten oder Gabionen wirken unterschiedlich und stellen unterschiedliche Anforderungen an Aufbau und Pflege. Wir besprechen Material, Farbe und Höhe im Zusammenhang mit Haus, Garten und angrenzenden Flächen. Auch der Verlauf ist wichtig: Ein Grundstück mit Gefälle benötigt andere Übergänge als eine ebene Fläche. Bestehende Mauern, Bäume und Wege werden bei der Planung berücksichtigt.\n\nBevor Sie einen Zaun montieren lassen, sollten Grundstücksgrenzen und erforderliche Abstimmungen geklärt sein. Wir sehen uns die vorgesehenen Standorte der Pfosten und den Untergrund an. Bei Toren besprechen wir Durchgangsbreite, Öffnungsrichtung und die Nutzung im Alltag. Die Montage wird auf das ausgewählte System und die örtlichen Bedingungen abgestimmt. Soll ein alter Zaun ersetzt werden, halten wir Rückbau und weitere Vorarbeiten im Angebot fest.\n\nDie Kosten beim Zaunbau hängen von Länge und Höhe, Material, Toren, Untergrund und Zugänglichkeit ab. Ein einfacher gerader Verlauf verursacht einen anderen Aufwand als mehrere Ecken oder starke Höhenunterschiede. Für Ihre Anfrage sind Fotos, eine ungefähre Länge und Ihre Vorstellungen zu Sichtschutz und Zugang hilfreich. Wir klären daraus die nächsten Schritte und erstellen ein Angebot für die vereinbarte Anlage einschließlich der besprochenen Montagearbeiten.","meta_title":"Zaunbau & Sichtschutz in Hattersheim | Loni GalaBau","meta_description":"Zaunbau in Hattersheim und Rhein-Main: Zäune, Gartentore und Sichtschutz montieren lassen. Material, Verlauf und Untergrund gemeinsam abstimmen.","geo_focus":"Hattersheim & Rhein-Main","custom_benefits":[{"t":"Gartenzäune montieren","d":"Material, Pfosten und Verlauf passend zu Grundstück, Nutzung und gewünschter Gestaltung abstimmen."},{"t":"Sichtschutz gestalten","d":"Private Gartenbereiche mit einer passenden Höhe und Materialwirkung einfassen."},{"t":"Tore und Zugänge","d":"Durchgangsbreite, Öffnungsrichtung und Anschlüsse für einen alltagstauglichen Zugang planen."}],"custom_faqs":[{"q":"Können Zaun und Sichtschutz kombiniert werden?","a":"Ja, unterschiedliche Gartenbereiche können verschiedene Anforderungen haben. Wir besprechen, wo eine offene Begrenzung genügt und wo Sichtschutz gewünscht ist. Das gewählte System und die örtlichen Bedingungen müssen dazu passen."},{"q":"Was sollte vor der Zaunmontage geklärt sein?","a":"Hilfreich sind ein geklärter Grenzverlauf, Informationen zu vorhandenen Leitungen und alle erforderlichen Abstimmungen. Teilen Sie uns auch mit, ob der Zaun an Mauern anschließt oder ein alter Zaun zurückgebaut werden soll."},{"q":"Lässt sich ein Zaun auch an einem Hang montieren?","a":"Das lässt sich anhand von Gefälle und Zaunsystem planen. Verlauf, Übergänge und Pfostenpositionen müssen zur Situation passen. Fotos und Angaben zum Höhenunterschied helfen bei der ersten Einschätzung."}],"expected_updated_at":"2026-09-28 14:38:07.846222+00"},{"slug":"rasenanlagen","short_text":"Rollrasen verlegen lassen oder Rasen neu einsäen: Wir bereiten die Fläche vor und stimmen Anlage, Bewässerung und erste Pflege mit Ihnen ab.","long_text":"Eine neue Rasenfläche soll zum Garten und zu ihrer späteren Nutzung passen. Loni GalaBau legt Rasenanlagen in Hattersheim und im Rhein-Main-Gebiet an. Sie können Rollrasen verlegen lassen oder sich für eine Einsaat entscheiden. Welche Variante zu Ihrem Vorhaben passt, besprechen wir anhand der Fläche, des gewünschten Zeitrahmens und der Möglichkeiten zur anschließenden Pflege.\n\nVor dem Grün kommt die Bodenvorbereitung. Wir betrachten den Zustand der vorhandenen Fläche, Höhen und Übergänge zu Wegen, Terrassen und Beeten. Je nach Bestand sind alte Rasensoden zu entfernen, Boden aufzubereiten oder Flächen neu zu modellieren. Welche Vorarbeiten erforderlich sind, wird im Leistungsumfang festgehalten. Auch Stellen, an denen sich Wasser sammelt, sollten vor der Neuanlage betrachtet werden.\n\nRollrasen bringt bereits eine geschlossene Grasnarbe mit; eine Einsaat entwickelt sich erst auf der vorbereiteten Fläche. Für beide Varianten sind die Bedingungen vor Ort und die Betreuung nach der Anlage wichtig. Wir stimmen die Ausführung mit Ihnen ab und besprechen Bewässerung, erste Pflege und Nutzung. Falls eine automatische Gartenbewässerung vorgesehen ist, lohnt es sich, die Leitungsplanung vor dem Anlegen des Rasens einzubeziehen.\n\nDie Kosten für das Verlegen von Rollrasen oder eine Einsaat hängen nicht allein von der Fläche ab. Rückbau, Bodenarbeiten, Material, Zufahrt und mögliche Entsorgung beeinflussen den Aufwand. Senden Sie uns Fotos und ungefähre Maße und beschreiben Sie, ob es sich um eine bestehende Rasenfläche oder eine Neuanlage handelt. Daraus klären wir die notwendigen Schritte und erstellen ein Angebot mit dem vereinbarten Umfang.","meta_title":"Rollrasen verlegen in Hattersheim | Loni GalaBau","meta_description":"Rollrasen verlegen lassen oder Rasen einsäen in Hattersheim und Rhein-Main. Bodenvorbereitung, Anlage und erste Pflege gemeinsam abstimmen.","geo_focus":"Hattersheim & Rhein-Main","custom_benefits":[{"t":"Rollrasen verlegen","d":"Fläche vorbereiten, Lieferung und Verlegung abstimmen und die erste Pflege besprechen."},{"t":"Rasen durch Einsaat anlegen","d":"Eine Alternative zur Rollrasenverlegung passend zu Grundstück, Nutzung und Zeitrahmen planen."},{"t":"Boden und Übergänge","d":"Vorarbeiten, Geländehöhen und Anschlüsse an Beete, Terrasse und Wege berücksichtigen."}],"custom_faqs":[{"q":"Wann kann Rollrasen verlegt werden?","a":"Ein geeigneter Termin hängt von Wetter, Bodenzustand, Materialverfügbarkeit und der anschließenden Bewässerung ab. Wir stimmen die Ausführung für Ihr Vorhaben ab; eine feste Jahreszeit allein ist noch keine Terminentscheidung."},{"q":"Wann darf die neue Rasenfläche genutzt werden?","a":"Das hängt vom Anwachsen, Wetter und der geplanten Belastung ab. Wir besprechen bei der Übergabe, worauf Sie bei Pflege und erster Nutzung achten sollen. Verlegter Rollrasen ist nicht sofort vollständig belastbar."},{"q":"Was gehört zum Angebot für das Verlegen von Rollrasen?","a":"Das Angebot sollte erkennen lassen, welche Bodenvorbereitung, Materialien und Verlegearbeiten vereinbart sind. Rückbau, Abtransport oder zusätzliche Bodenarbeiten können den Umfang verändern und werden für Ihre Fläche abgestimmt."}],"expected_updated_at":"2026-09-28 14:38:08.001816+00"},{"slug":"erdarbeiten","short_text":"Erdarbeiten und Baggerarbeiten für Garten und Außenanlage: Aushub, Geländeanpassung und Bodenvorbereitung als Grundlage für die nächsten Bauarbeiten.","long_text":"Bevor eine Terrasse, ein Gartenweg oder eine neue Rasenfläche entsteht, muss der Untergrund dazu passen. Loni GalaBau übernimmt Erdarbeiten im Garten und an Außenanlagen in Hattersheim und im Rhein-Main-Gebiet. Wir heben Boden aus, passen Geländehöhen an und bereiten die vereinbarten Flächen für die folgenden Arbeiten vor. Den Umfang richten wir nach Ihrem Vorhaben und dem vorhandenen Grundstück aus.\n\nWenn Sie Ihren Garten begradigen lassen möchten, klären wir zuerst die geplanten Höhen und welche Anschlüsse erhalten bleiben. Haus, Wege, Nachbarflächen und die geplante Entwässerung gehören dabei zusammen betrachtet. Bei einem bestehenden Garten berücksichtigen wir außerdem Pflanzen und Bauteile, die erhalten werden sollen. Vorhandene Informationen zu Leitungen und Einbauten helfen, die Arbeiten vorzubereiten und offene Fragen vor Beginn zu klären.\n\nFür Baggerarbeiten setzen wir unseren Fuhrpark passend zur Aufgabe ein. Wie die Baustelle erreichbar ist, beeinflusst den Ablauf wesentlich: Torbreite, Durchfahrt, Tragfähigkeit der Zufahrt und Platz für Material oder Fahrzeuge spielen eine Rolle. Deshalb besprechen wir die Zugänglichkeit frühzeitig. Ob Boden auf dem Grundstück weiterverwendet werden kann oder abgefahren werden muss, hängt von seiner Beschaffenheit und der Planung ab.\n\nDie Kosten der Erdarbeiten ergeben sich aus Umfang, Bodenverhältnissen, Maschinenzugang, Transport und vereinbarter Entsorgung. Ein Flächenmaß allein reicht dafür häufig nicht aus. Für Ihre Anfrage helfen Fotos, ungefähre Maße, Angaben zu Höhenunterschieden und ein kurzer Hinweis auf das geplante Ergebnis. Wir stimmen die notwendigen Vorarbeiten mit Ihnen ab und halten fest, welche Leistungen im Angebot enthalten sind und wie sie mit Pflasterarbeiten, Entwässerung oder Gartengestaltung zusammenhängen.","meta_title":"Erdarbeiten & Baggerarbeiten Hattersheim | Loni GalaBau","meta_description":"Erdarbeiten in Hattersheim und Rhein-Main: Aushub, Geländeanpassung und Bodenvorbereitung für Garten und Außenanlage. Vorhaben persönlich abstimmen.","geo_focus":"Hattersheim & Rhein-Main","custom_benefits":[{"t":"Aushub und Vorbereitung","d":"Boden für die vereinbarten Garten-, Wege- und Terrassenarbeiten abtragen und Flächen vorbereiten."},{"t":"Geländehöhen anpassen","d":"Übergänge und geplante Höhen im Zusammenhang mit Haus, Garten und Entwässerung betrachten."},{"t":"Maschinen und Transport","d":"Bagger, Radlader und Materialtransport entsprechend Aufgabe und Zufahrt einplanen."}],"custom_faqs":[{"q":"Sind Baggerarbeiten bei einer schmalen Gartenzufahrt möglich?","a":"Das hängt von Breite, Höhe, Tragfähigkeit und Bewegungsraum ab. Senden Sie uns Fotos und Maße der Zufahrt. Wir klären, welcher Maschineneinsatz möglich ist und wie sich der Zugang auf den Aufwand auswirkt."},{"q":"Wird der Erdaushub auch abgefahren?","a":"Abtransport und Entsorgung werden nach Menge, Bodenbeschaffenheit und vereinbartem Umfang berücksichtigt. Eine mögliche Wiederverwendung auf dem Grundstück besprechen wir ebenfalls. Diese Leistungen sollten im Angebot ausdrücklich beschrieben sein."},{"q":"Welche Angaben werden für Erdarbeiten im Garten benötigt?","a":"Hilfreich sind das gewünschte Ergebnis, ungefähre Flächen und Höhen, Fotos der Zufahrt sowie vorhandene Leitungsinformationen. Je klarer Ausgangslage und Anschlussarbeiten sind, desto gezielter lassen sich die Vorarbeiten abstimmen."}],"expected_updated_at":"2026-09-28 14:38:08.117742+00"},{"slug":"entwaesserung","short_text":"Entwässerung für Garten, Einfahrt und Terrasse: Wir betrachten Gefälle, Rinnen, Abläufe und mögliche Versickerung im Zusammenhang mit Ihrem Grundstück.","long_text":"Wenn Regenwasser auf der Einfahrt stehen bleibt oder sich an der Terrasse sammelt, lohnt sich ein Blick auf die gesamte Wasserführung. Loni GalaBau plant und baut Entwässerungslösungen für Außenanlagen in Hattersheim und im Rhein-Main-Gebiet. Wir betrachten, wo Wasser anfällt, wie die Flächen geneigt sind und wohin es geführt werden kann. Die passende Lösung ergibt sich aus der Situation vor Ort.\n\nFür befestigte Flächen können Entwässerungsrinnen und Abläufe Teil des Aufbaus sein. Im Garten kommen je nach Boden und Ausgangslage auch Drainagen oder Versickerungslösungen infrage. Eine einzelne Rinne oder ein Rohr löst das Problem jedoch nicht automatisch: Höhen, Gefälle, Aufnahme des Wassers und ein geeigneter weiterer Weg müssen zusammenpassen. Deshalb stimmen wir die Entwässerung mit vorhandenen oder geplanten Pflaster- und Gartenflächen ab.\n\nBevor wir eine Drainage verlegen oder eine Versickerung vorsehen, müssen Bodenverhältnisse, Anschlussmöglichkeiten und örtliche Vorgaben geklärt sein. Vorhandene Pläne und Informationen zur bisherigen Entwässerung sind dafür hilfreich. Bei einer Umgestaltung prüfen wir, welche Elemente erhalten bleiben können und welche Übergänge angepasst werden müssen. Den konkreten Aufbau und die erforderlichen Arbeiten besprechen wir für Ihr Grundstück.\n\nDie Kosten hängen unter anderem von Fläche, Leitungswegen, Einbautiefe, Erdarbeiten und Wiederherstellung vorhandener Beläge ab. Für eine erste Anfrage helfen Fotos der betroffenen Bereiche, eine Skizze und Ihre Beobachtungen bei Regen. Beschreiben Sie auch, ob das Problem neu aufgetreten ist oder schon länger besteht. Nach Klärung der Ausgangslage erhalten Sie ein Angebot für die abgestimmten Maßnahmen und Hinweise zur späteren Kontrolle und Pflege.","meta_title":"Entwässerung in Hattersheim | Loni GalaBau","meta_description":"Entwässerung für Garten, Einfahrt und Terrasse in Hattersheim und Rhein-Main. Gefälle, Rinnen und mögliche Drainage auf Ihr Grundstück abstimmen.","geo_focus":"Hattersheim & Rhein-Main","custom_benefits":[{"t":"Rinnen und Abläufe","d":"Regenwasser an befestigten Flächen aufnehmen und die weitere Wasserführung abstimmen."},{"t":"Drainage und Versickerung","d":"Eignung, Bodenverhältnisse und Anschlussmöglichkeiten für das Grundstück klären."},{"t":"Gefälle und Anschlüsse","d":"Entwässerung mit Pflasterflächen, Terrassenhöhen und Übergängen zusammen planen."}],"custom_faqs":[{"q":"Hilft eine Drainage bei Staunässe im Garten?","a":"Das hängt von der Ursache, dem Boden und der möglichen Wasserableitung ab. Eine Drainage ist nicht auf jedem Grundstück die passende Lösung. Zuerst müssen Ausgangslage und weitere Wasserführung geklärt werden."},{"q":"Kann eine Entwässerungsrinne in einer bestehenden Einfahrt ergänzt werden?","a":"Eine Nachrüstung lässt sich prüfen. Dabei sind Höhen, Gefälle, Anschlüsse und die Wiederherstellung des Belags wichtig. Fotos und Angaben zur bisherigen Wasserführung helfen bei der ersten Einschätzung."},{"q":"Wie bleiben Entwässerungsrinnen funktionsfähig?","a":"Rinnen und Abläufe müssen entsprechend dem eingesetzten System kontrolliert und von Laub oder Schmutz freigehalten werden. Wir besprechen bei der Übergabe, welche Bauteile zugänglich bleiben sollen und welche Pflege vorgesehen ist."}],"expected_updated_at":"2026-09-28 14:38:08.242719+00"}]$seo_data$::jsonb)
    AS p(slug text, short_text text, long_text text, meta_title text, meta_description text,
         geo_focus text, custom_benefits jsonb, custom_faqs jsonb, expected_updated_at timestamptz)
  WHERE s.slug = p.slug AND s.active = true AND s.updated_at = p.expected_updated_at;
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  IF updated_count <> 8 THEN
    RAISE EXCEPTION 'SEO update cancelled: expected 8 unchanged services, found %', updated_count;
  END IF;
END $apply_seo$;
